package com.abdickers.realms;

import android.app.Activity;
import android.content.Intent;
import android.net.Uri;
import android.os.Bundle;
import android.view.View;
import android.widget.*;
import net.openid.appauth.*;
import org.json.JSONObject;
import java.util.*;
import java.util.concurrent.Executors;

/** Provider-owned browser consent, returning directly to the app with PKCE. */
public final class SlackOAuthActivity extends Activity {
 private static final int AUTHORIZE=8221;private AuthorizationService service;private TextView status;private Button retry;private boolean closed;private long generation;
 static AuthorizationServiceConfiguration configuration(){return new AuthorizationServiceConfiguration(Uri.parse("https://slack.com/oauth/v2/authorize"),Uri.parse("https://slack.com/api/oauth.v2.access"));}
 @Override protected void onCreate(Bundle state){super.onCreate(state);generation=state==null?Connections.generation(this):state.getLong("generation");LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,70,24,24);root.setBackgroundColor(0xFF171D23);status=new TextView(this);status.setTextColor(0xFFE8EDF4);status.setTextSize(19);status.setText("Connect Slack · Spirit of 76 Fireworks");root.addView(status);retry=new Button(this);retry.setText("Try Slack sign-in again");retry.setVisibility(View.GONE);retry.setOnClickListener(v->begin());root.addView(retry);Button back=new Button(this);back.setText("Back to accounts");back.setOnClickListener(v->finish());root.addView(back);setContentView(root);service=new AuthorizationService(this);if(state==null)begin();else fail("If Slack sign-in was interrupted, try again.");}
 private void begin(){try{if(!BuildConfig.SLACK_CLIENT_ID.matches("[0-9]+\\.[0-9]+")){fail("The app’s Slack connection is still being prepared.");return;}if(!WidgetState.prefs(this).getBoolean("work_google_connected",false)){fail("Sign in to Work with Google first, then connect Slack.");return;}retry.setVisibility(View.GONE);generation=Connections.generation(this);AuthorizationRequest request=new AuthorizationRequest.Builder(configuration(),BuildConfig.SLACK_CLIENT_ID,ResponseTypeValues.CODE,Uri.parse(SlackConnection.REDIRECT)).setAdditionalParameters(Map.of("user_scope",SlackConnection.SCOPES,"team","T2X5T3JRE")).build();Vault.put(this,"slack_pending",new JSONObject().put("request",request.jsonSerialize()).put("time",System.currentTimeMillis()).toString());status.setText("Finish connecting Slack in the browser. You can use your Work Google account there.");startActivityForResult(service.getAuthorizationRequestIntent(request),AUTHORIZE);}catch(Exception e){fail("Slack sign-in could not open. Check your connection and try again.");}}
 @Override protected void onActivityResult(int request,int result,Intent intent){super.onActivityResult(request,result,intent);if(request!=AUTHORIZE)return;try{String pending=Vault.get(this,"slack_pending");Vault.put(this,"slack_pending","");AuthorizationResponse response=intent==null?null:AuthorizationResponse.fromIntent(intent);AuthorizationException error=intent==null?null:AuthorizationException.fromIntent(intent);if(result!=RESULT_OK||response==null||error!=null){fail(OAuthFeedback.failure("Slack",error));return;}JSONObject record=new JSONObject(pending);AuthorizationRequest original=AuthorizationRequest.jsonDeserialize(record.getJSONObject("request"));long age=System.currentTimeMillis()-record.getLong("time");if(age<0||age>1800000||!Objects.equals(original.state,response.request.state)||!Objects.equals(original.codeVerifier,response.request.codeVerifier)||!BuildConfig.SLACK_CLIENT_ID.equals(response.request.clientId)||!SlackConnection.REDIRECT.equals(response.request.redirectUri.toString())||!configuration().authorizationEndpoint.equals(response.request.configuration.authorizationEndpoint)||!SlackConnection.SCOPES.equals(response.request.additionalParameters.get("user_scope")))throw new IllegalStateException();status.setText("Checking your Slack account…");var executor=Executors.newSingleThreadExecutor();executor.execute(()->{try{JSONObject session=SlackConnection.exchange(response.authorizationCode,original.codeVerifier,BuildConfig.SLACK_CLIENT_ID,SlackConnection.NETWORK,System.currentTimeMillis());if(closed)return;SlackConnection.install(this,session,generation);runOnUiThread(()->{if(!closed){setResult(RESULT_OK);CommandWidget.updateAll(this);finish();}});}catch(Exception e){runOnUiThread(()->fail(e instanceof IllegalStateException?e.getMessage():"Slack could not be connected. Try again; your other connections are unchanged."));}finally{executor.shutdown();}});}catch(Exception e){fail("This Slack sign-in expired or could not be verified. Please try again.");}}
 private void fail(String message){if(!closed){status.setText(message);retry.setVisibility(View.VISIBLE);}}
 @Override protected void onSaveInstanceState(Bundle out){out.putLong("generation",generation);super.onSaveInstanceState(out);}
 @Override protected void onDestroy(){closed=true;if(service!=null)service.dispose();super.onDestroy();}
}
